${pagingTop}
SELECT
	book_express_idx, library_code, agency_name, agency_id, book_reg_no,
	book_call_no, book_name, thumb_image, request_status, request_date,
	request_name, request_phone, reason, add_date, add_id
FROM
	BOOK_EXPRESS
WHERE

	
	request_status != '0'
	
	
	request_status = #{request_status}
	


AND	library_code = #{library_code}


AND	agency_id = #{agency_id}


AND	${search_type} LIKE '%'||#{search_text}||'%'

ORDER BY request_date DESC
${pagingBottom}

SELECT
	COUNT(*)
FROM
	BOOK_EXPRESS
WHERE

	
	request_status != '0'
	
	
	request_status = #{request_status}
	


AND	library_code = #{library_code}


AND	agency_id = #{agency_id}


AND	${search_type} LIKE '%'||#{search_text}||'%'

SELECT MAX(DECODE(request_status, 1, cnt, 0)) AS status1, MAX(DECODE(request_status, 2, cnt, 0)) AS status2, MAX(DECODE(request_status, 3, cnt, 0)) AS status3, MAX(DECODE(request_status, 4, cnt, 0)) AS status4, MAX(DECODE(request_status, 5, cnt, 0)) AS status5, MAX(DECODE(request_status, 6, cnt, 0)) AS status6 FROM ( SELECT request_status, COUNT(*) AS cnt FROM BOOK_EXPRESS
AND library_code = #{library_code}
AND agency_id = #{agency_id}
AND ${search_type} LIKE '%'||#{search_text}||'%'
GROUP BY request_status )

